const CACHE="mono-mock-v58";const ASSETS=["./assets/reference/limits-sticker-hq.png","./assets/reference/market-eyes-hq.png","./assets/reference/market-owl-hq.png","./sharp-icons.js?v=58","./bank-detail.js?v=58","./bank-detail.css?v=58","./assets/reference/transfer-pattern.svg","./icon-catalog.js?v=58","./mobile-stability.js?v=58","./mobile-stability.css?v=58","./pull-refresh.js?v=58","./hosted-storage.js?v=58","./card-stable.js?v=58","./card-stable.css?v=58","./profile-pwa.js?v=58","./profile-pwa.css?v=58","./history-glass.js?v=58","./history-glass.css?v=58","./faithful.css?v=58","./faithful-motion.js?v=58","./faithful-entry.js?v=58","./receipt-links.js?v=58","./native-reference.js?v=58","./native-reference.css?v=58","./reference-fidelity.js?v=58","./reference-fidelity.css?v=58","./continuity.js?v=58","./continuity.css?v=58","./motion.js?v=58","./motion.css?v=58","./recording.js?v=58","./recording.css?v=58","./interactions.js?v=58","./interactions.css?v=58","./surfaces.js?v=58","./surfaces.css?v=58","./refinement.css?v=58","./refinement.js?v=58","./reference.css?v=58","./experience.js?v=58","./style.css?v=58","./app.js?v=58","./manifest.json","./icon.svg","./icon.png","./pwa-runtime.js?v=58","./pwa-runtime.css?v=58","./admin-manifest.json"];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS)).then(()=>self.skipWaiting()))});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith('mono-mock-')&&key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',event=>{const request=event.request,url=new URL(request.url);if(request.method!=='GET'||url.origin!==self.location.origin||url.pathname.startsWith('/api/'))return;
 if(request.mode==='navigate'){event.respondWith(fetch(new Request(request,{cache:'no-store'})).catch(()=>new Response('<!doctype html><meta name="viewport" content="width=device-width"><style>html{background:#161616;color:white;font:18px system-ui;padding:24px}</style>Потрібне з’єднання з інтернетом. Відкрийте застосунок повторно після підключення.',{headers:{'Content-Type':'text/html; charset=utf-8'}})));return}
 event.respondWith(fetch(request).then(response=>{if(response.ok&&url.pathname.startsWith('/assets/')){const copy=response.clone();event.waitUntil(caches.open(CACHE).then(cache=>cache.put(request,copy)))}return response}).catch(()=>caches.match(request).then(cached=>cached||Response.error())))
});
